  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; }
button { font: inherit; }

.shell {
  width: min(1100px, calc(100% - 32px));
  margin: 0 auto;
  padding: 32px 0;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: center;
  margin-bottom: 20px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  color: #3662ff;
  font-size: 12px;
  font-weight: 800;
  margin: 0 0 6px;
}

h1 { margin: 0; font-size: clamp(32px, 5vw, 56px); line-height: .95; }
h2 { margin: 0 0 12px; font-size: 18px; }
.subtle { margin: 10px 0 0; color: #61708a; }
.session { background: #fff; padding: 12px 16px; border-radius: 999px; box-shadow: 0 10px 30px rgba(26, 38, 67, .08); white-space: nowrap; }

.status-bar {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}
.status-bar > div, .panel {
  background: rgba(255,255,255,.9);
  border: 1px solid rgba(117, 132, 164, .18);
  border-radius: 18px;
  box-shadow: 0 16px 40px rgba(35, 53, 84, .08);
}
.status-bar > div { padding: 18px; }
.status-bar strong { display: block; font-size: 32px; }
.status-bar span { color: #66758e; }

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 16px;
}

button {
  border: 0;
  border-radius: 12px;
  padding: 10px 14px;
  background: #315cff;
  color: #fff;
  cursor: pointer;
  font-weight: 700;
  box-shadow: 0 10px 24px rgba(49, 92, 255, .22);
}
button:hover:not(:disabled) { transform: translateY(-1px); }
button:disabled { cursor: not-allowed; opacity: .45; box-shadow: none; }
button.secondary { background: #e5eaf4; color: #27344b; box-shadow: none; }
.hold-info { margin-left: auto; color: #44536c; font-weight: 700; }

.screen {
  margin: 28px auto 24px;
  width: min(720px, 85%);
  text-align: center;
  letter-spacing: .35em;
  font-size: 12px;
  font-weight: 800;
  color: #6f7c92;
  background: linear-gradient(180deg, #c9d5e8, #f8fafc);
  border-radius: 10px 10px 60px 60px;
  padding: 12px;
  box-shadow: inset 0 -10px 20px rgba(0,0,0,.04);
}

.seat-grid {
  display: grid;
  gap: 10px;
  overflow-x: auto;
  padding: 8px 0 20px;
}
.seat-row { display: grid; grid-template-columns: 34px repeat(10, 1fr); gap: 8px; min-width: 650px; align-items: center; }
.row-label { font-weight: 900; color: #536178; text-align: center; }
.seat {
  aspect-ratio: 1.25;
  min-height: 46px;
  padding: 0;
  border-radius: 12px 12px 18px 18px;
  color: #162033;
  background: #fff;
  border: 2px solid transparent;
  box-shadow: 0 8px 18px rgba(33, 49, 82, .08);
}
.seat.available { background: #e9fff2; border-color: #57d687; }
.seat.held { background: #fff4d7; border-color: #f0ba38; }
.seat.booked { background: #f0f2f6; color: #8792a3; border-color: #c4ccda; }
.seat.selected { outline: 3px solid #315cff; background: #dbe5ff; }
.seat.mine { box-shadow: 0 0 0 3px rgba(49, 92, 255, .24), 0 8px 18px rgba(33, 49, 82, .08); }
.seat.conflict { animation: pulse .8s ease-in-out 3; border-color: #ed4956; }
@keyframes pulse { 50% { transform: scale(1.07); } }

.log-panel { margin-top: 18px; padding: 18px; }
ul { margin: 0; padding-left: 20px; color: #4e5e77; }
li.error { color: #b4232f; font-weight: 700; }

@media (max-width: 720px) {
  .hero { align-items: flex-start; flex-direction: column; }
  .status-bar { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .hold-info { width: 100%; margin-left: 0; }
}
"}

{"path": "package.json", "content": "{
  "name": "seat-booking",
  "version": "1.0.0",
  "description": "Concurrent-safe seat booking demo with PGLite, Express, SSE and Vite.",
  "type": "module",
  "scripts": {
    "dev": "node scripts/dev.js",
    "server": "node server/index.js",
    "client": "vite --host 0.0.0.0",
    "start": "node server/index.js",
    "build": "vite build"
  },
  "dependencies": {
    "@electric-sql/pglite": "^0.2.17",
    "@vitejs/plugin-basic-ssl": "latest",
