{"path": "server/index.js", "content": "import express from 'express';
import cors from 'cors';
import { PGlite } from '@electric-sql/pglite';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const PORT = Number(process.env.PORT || 3001);
const CLIENT_DIR = path.join(__dirname, '..', 'dist');
const DB_DIR = process.env.PGLITE_DATA_DIR || path.join(__dirname, '..', 'data', 'pglite');
const ROWS = ['A', 'B', 'C', 'D', 'E'];
const SEATS_PER_ROW = 10;
const HOLD_TTL_SECONDS = Number(process.env.HOLD_TTL_SECONDS || 60);
const SWEEP_INTERVAL_MS = Number(process.env.SWEEP_INTERVAL_MS || 1000);

const app = express();
const db = new PGlite(DB_DIR);
const clients = new Set();

// PGlite runs in-process. This queue serialises multi-statement transactional
// units so Express cannot interleave BEGIN/COMMIT sections on the same handle.
let txQueue = Promise.resolve();
function withTransaction(fn) {
  const run = txQueue.then(async () => {
    await db.query('BEGIN');
    try {
      const value = await fn();
      await db.query('COMMIT');
      return value;
    } catch (err) {
      try {
        await db.query('ROLLBACK');
      } catch (_) {
        // Ignore rollback failures; preserve original error.
      }
      throw err;
    }
  });
  txQueue = run.catch(() => {});
  return run;
}

function sendError(res, status, message, extra = {}) {
  res.status(status).json({ error: message, ...extra });
}

function normaliseSeatIds(seatIds) {
  if (!Array.isArray(seatIds) || seatIds.length === 0) return null;
  const ids = [...new Set(seatIds.map(Number))].filter((id) => Number.isInteger(id) && id > 0);
  return ids.length === seatIds.length ? ids : null;
}

function publicSeat(row) {
  return {
    id: row.id,
    rowLabel: row.row_label,
    seatNumber: row.seat_number,
    status: row.status,
    holdId: row.hold_id,
    holdExpiresAt: row.hold_expires_at,
    bookedBy: row.booked_by,
  };
}

function broadcast(event, payload) {
  const data = `event: ${event}\ndata: ${JSON.stringify(payload)}\n\n`;
  for (const res of clients) {
    try {
      res.write(data);
    } catch (_) {
      clients.delete(res);
    }
  }
}

async function broadcastSeats(seatIds, event = 'seats') {
  if (!seatIds?.length) return;
  const { rows } = await db.query(
    `SELECT id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by
       FROM seats
      WHERE id = ANY($1::int[])
      ORDER BY id`,
    [seatIds],
  );
  broadcast(event, { seats: rows.map(publicSeat), seatIds });
}

async function releaseExpiredHoldsInCurrentTx() {
  const { rows } = await db.query(
    `UPDATE seats
        SET status = 'available', hold_id = NULL, hold_expires_at = NULL
      WHERE status = 'held'
        AND hold_expires_at <= NOW()
      RETURNING id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by`,
  );
  return rows;
}

async function sweepExpiredHolds() {
  try {
    const released = await withTransaction(() => releaseExpiredHoldsInCurrentTx());
    if (released.length) {
      broadcast('seats', { seats: released.map(publicSeat), seatIds: released.map((s) => s.id), reason: 'expired' });
    }
  } catch (err) {
    console.error('expiry sweep failed:', err);
  }
}

async function initialiseDatabase() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS seats (
      id SERIAL PRIMARY KEY,
      row_label TEXT NOT NULL,
      seat_number INTEGER NOT NULL,
      status TEXT NOT NULL CHECK (status IN ('available', 'held', 'booked')) DEFAULT 'available',
      hold_id TEXT,
      hold_expires_at TIMESTAMPTZ,
      booked_by TEXT,
      booked_at TIMESTAMPTZ,
      UNIQUE(row_label, seat_number),
      CHECK (
        (status = 'available' AND hold_id IS NULL AND hold_expires_at IS NULL AND booked_by IS NULL) OR
        (status = 'held' AND hold_id IS NOT NULL AND hold_expires_at IS NOT NULL AND booked_by IS NULL) OR
        (status = 'booked' AND hold_id IS NOT NULL AND booked_by IS NOT NULL)
      )
    );

    CREATE TABLE IF NOT EXISTS holds (
      id TEXT PRIMARY KEY,
      session_id TEXT NOT NULL,
      seat_ids INTEGER[] NOT NULL,
      expires_at TIMESTAMPTZ NOT NULL,
      status TEXT NOT NULL CHECK (status IN ('active', 'confirmed', 'released', 'expired')) DEFAULT 'active',
      booking_id TEXT,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      confirmed_at TIMESTAMPTZ
    );

    CREATE INDEX IF NOT EXISTS idx_seats_status_expiry ON seats(status, hold_expires_at);
    CREATE INDEX IF NOT EXISTS idx_seats_hold_id ON seats(hold_id);
  `);

  const { rows } = await db.query('SELECT COUNT(*)::int AS count FROM seats');
  if (rows[0].count === 0) {
    for (const rowLabel of ROWS) {
      for (let seatNumber = 1; seatNumber <= SEATS_PER_ROW; seatNumber += 1) {
        await db.query('INSERT INTO seats (row_label, seat_number) VALUES ($1, $2)', [rowLabel, seatNumber]);
      }
    }
  }
}

app.use(cors());
app.use(express.json());

app.get('/api/health', (_req, res) => {
  res.json({ ok: true });
});

app.get('/api/stream', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache, no-transform',
    Connection: 'keep-alive',
    'X-Accel-Buffering': 'no',
  });
  res.write(`event: connected\ndata: ${JSON.stringify({ ok: true, ttlSeconds: HOLD_TTL_SECONDS })}\n\n`);
  clients.add(res);
  req.on('close', () => clients.delete(res));
});

app.get('/api/seats', async (_req, res, next) => {
  try {
    const released = await withTransaction(() => releaseExpiredHoldsInCurrentTx());
    if (released.length) {
      broadcast('seats', { seats: released.map(publicSeat), seatIds: released.map((s) => s.id), reason: 'expired' });
    }
    const { rows } = await db.query(
      `SELECT id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by
         FROM seats
        ORDER BY row_label, seat_number`,
    );
    const totals = rows.reduce((acc, row) => {
      acc[row.status] += 1;
      return acc;
    }, { available: 0, held: 0, booked: 0 });
    res.json({ seats: rows.map(publicSeat), totals, ttlSeconds: HOLD_TTL_SECONDS });
  } catch (err) {
    next(err);
  }
});

app.post('/api/holds', async (req, res, next) => {
  try {
    const seatIds = normaliseSeatIds(req.body?.seatIds);
    const sessionId = String(req.body?.sessionId || '').trim();
    if (!seatIds) return sendError(res, 400, 'seatIds must be a non-empty array of positive integers with no duplicates');
    if (!sessionId) return sendError(res, 400, 'sessionId is required');

    const result = await withTransaction(async () => {
      await releaseExpiredHoldsInCurrentTx();

      const existing = await db.query(
        `SELECT id, status
           FROM seats
          WHERE id = ANY($1::int[])
          ORDER BY id`,
        [seatIds],
      );
      const foundIds = new Set(existing.rows.map((r) => r.id));
      const conflicts = existing.rows.filter((r) => r.status !== 'available').map((r) => r.id);
      for (const id of seatIds) if (!foundIds.has(id)) conflicts.push(id);
      if (existing.rows.length !== seatIds.length || conflicts.length) {
        return { ok: false, conflicts: [...new Set(conflicts)].sort((a, b) => a - b) };
      }

      const holdId = randomUUID();
      const expires = await db.query(`SELECT NOW() + ($1::int * INTERVAL '1 second') AS expires_at`, [HOLD_TTL_SECONDS]);
      const expiresAt = expires.rows[0].expires_at;

      const updated = await db.query(
        `UPDATE seats
            SET status = 'held', hold_id = $1, hold_expires_at = $2
          WHERE id = ANY($3::int[])
            AND status = 'available'
          RETURNING id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by`,
        [holdId, expiresAt, seatIds],
      );
      if (updated.rows.length !== seatIds.length) {
        return { ok: false, conflicts: seatIds };
      }

      await db.query(
        `INSERT INTO holds (id, session_id, seat_ids, expires_at)
         VALUES ($1, $2, $3::int[], $4)`,
        [holdId, sessionId, seatIds, expiresAt],
      );

      return { ok: true, hold: { id: holdId, sessionId, seatIds, expiresAt, ttlSeconds: HOLD_TTL_SECONDS }, seats: updated.rows };
    });

    if (!result.ok) return sendError(res, 409, 'One or more seats are unavailable', { conflictSeatIds: result.conflicts });
    broadcast('seats', { seats: result.seats.map(publicSeat), seatIds: result.seats.map((s) => s.id), reason: 'held' });
    res.status(201).json({ hold: result.hold, seats: result.seats.map(publicSeat) });
  } catch (err) {
    next(err);
  }
});

app.post('/api/holds/:holdId/confirm', async (req, res, next) => {
  try {
    const holdId = req.params.holdId;
    const sessionId = String(req.body?.sessionId || '').trim();
    if (!sessionId) return sendError(res, 400, 'sessionId is required');

    const result = await withTransaction(async () => {
      await releaseExpiredHoldsInCurrentTx();

      const holdRes = await db.query('SELECT * FROM holds WHERE id = $1', [holdId]);
      if (!holdRes.rows.length) return { ok: false, status: 404, message: 'Unknown hold' };
      const hold = holdRes.rows[0];
      if (hold.session_id !== sessionId) return { ok: false, status: 403, message: 'Hold belongs to a different session' };

      if (hold.status === 'confirmed') {
        const seats = await db.query(
          `SELECT id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by
             FROM seats
            WHERE hold_id = $1 AND status = 'booked'
            ORDER BY id`,
          [holdId],
        );
        return { ok: true, idempotent: true, bookingId: hold.booking_id, seats: seats.rows };
      }
      if (hold.status !== 'active') return { ok: false, status: 409, message: `Hold is ${hold.status}` };

      const activeSeats = await db.query(
        `SELECT id
           FROM seats
          WHERE id = ANY($1::int[])
            AND hold_id = $2
            AND status = 'held'
            AND hold_expires_at > NOW()`,
        [hold.seat_ids, holdId],
      );
      if (activeSeats.rows.length !== hold.seat_ids.length) {
        await db.query("UPDATE holds SET status = 'expired' WHERE id = $1 AND status = 'active'", [holdId]);
        return { ok: false, status: 409, message: 'Hold has expired or no longer owns all seats' };
      }

      const bookingId = randomUUID();
      const booked = await db.query(
        `UPDATE seats
            SET status = 'booked', booked_by = $1, booked_at = NOW(), hold_expires_at = NULL
          WHERE id = ANY($2::int[])
            AND hold_id = $3
            AND status = 'held'
          RETURNING id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by`,
        [sessionId, hold.seat_ids, holdId],
      );
      if (booked.rows.length !== hold.seat_ids.length) {
        throw new Error('Invariant violation while confirming hold');
      }
      await db.query(
        `UPDATE holds
            SET status = 'confirmed', booking_id = $1, confirmed_at = NOW()
          WHERE id = $2`,
        [bookingId, holdId],
      );
      return { ok: true, idempotent: false, bookingId, seats: booked.rows };
    });

    if (!result.ok) return sendError(res, result.status, result.message);
    if (!result.idempotent) {
      broadcast('seats', { seats: result.seats.map(publicSeat), seatIds: result.seats.map((s) => s.id), reason: 'booked' });
    }
    res.json({ booking: { id: result.bookingId, holdId, seatIds: result.seats.map((s) => s.id) }, seats: result.seats.map(publicSeat), idempotent: result.idempotent });
  } catch (err) {
    next(err);
  }
});

app.delete('/api/holds/:holdId', async (req, res, next) => {
  try {
    const holdId = req.params.holdId;
    const sessionId = String(req.body?.sessionId || req.query?.sessionId || '').trim();
    if (!sessionId) return sendError(res, 400, 'sessionId is required');

    const result = await withTransaction(async () => {
      await releaseExpiredHoldsInCurrentTx();
      const holdRes = await db.query('SELECT * FROM holds WHERE id = $1', [holdId]);
      if (!holdRes.rows.length) return { ok: false, status: 404, message: 'Unknown hold' };
      const hold = holdRes.rows[0];
      if (hold.session_id !== sessionId) return { ok: false, status: 403, message: 'Hold belongs to a different session' };
      if (hold.status !== 'active') return { ok: true, seats: [], already: hold.status };

      const released = await db.query(
        `UPDATE seats
            SET status = 'available', hold_id = NULL, hold_expires_at = NULL
          WHERE hold_id = $1 AND status = 'held'
          RETURNING id, row_label, seat_number, status, hold_id, hold_expires_at, booked_by`,
        [holdId],
      );
      await db.query("UPDATE holds SET status = 'released' WHERE id = $1", [holdId]);
      return { ok: true, seats: released.rows };
    });

    if (!result.ok) return sendError(res, result.status, result.message);
    if (result.seats.length) {
      broadcast('seats', { seats: result.seats.map(publicSeat), seatIds: result.seats.map((s) => s.id), reason: 'released' });
    }
    res.json({ released: result.seats.map(publicSeat), already: result.already || null });
  } catch (err) {
    next(err);
  }
});

app.use(express.static(CLIENT_DIR));
app.get('*', (req, res, next) => {
  if (req.path.startsWith('/api/')) return next();
  res.sendFile(path.join(CLIENT_DIR, 'index.html'));
});

app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal server error' });
});

await initialiseDatabase();
setInterval(sweepExpiredHolds, SWEEP_INTERVAL_MS).unref();

app.listen(PORT, () => {
  console.log(`Seat booking API listening on http://localhost:${PORT}`);
  console.log(`PGLite data directory: ${DB_DIR}`);
});
"}

{"path": "scripts/dev.js", "content": "import { spawn } from 'node:child_process';

const children = [
  spawn(process.execPath, ['server/index.js'], { stdio: 'inherit', env: { ...process.env, PORT: process.env.PORT || '3001' } }),
  spawn(process.platform === 'win32' ? 'npx.cmd' : 'npx', ['vite', '--host', '0.0.0.0'], { stdio: 'inherit', env: { ...process.env, VITE_API_BASE: process.env.VITE_API_BASE || 'http://localhost:3001' } }),
];

function stop(signal = 'SIGTERM') {
  for (const child of children) child.kill(signal);
}

process.on('SIGINT', () => stop('SIGINT'));
process.on('SIGTERM', () => stop('SIGTERM'));

for (const child of children) {
  child.on('exit', (code, signal) => {
    if (code && code !== 0) console.error(`dev child exited with code ${code}`);
    stop(signal || 'SIGTERM');
  });
}
"}

{"path": "src/main.js", "content": "import './styles.css';

const API_BASE = (import.meta.env.VITE_API_BASE || '').replace(/\/$/, '');
const app = document.querySelector('#app');
const sessionId = getSessionId();

let seats = [];
let selected = new Set();
let currentHold = null;
let countdownTimer = null;
let lastConflictIds = new Set();

app.innerHTML = `
  <main class="shell">
    <header class="hero">
      <div>
        <p class="eyebrow">Single event</p>
        <h1>Live Seat Booking</h1>
        <p class="subtle">Select available seats, place a temporary hold, then confirm before the timer expires.</p>
      </div>
      <div class="session">Session <code>${sessionId.slice(0, 8)}</code></div>
    </header>

    <section class="status-bar">
      <div><strong id="availableCount">0</strong><span>Available</span></div>
      <div><strong id="heldCount">0</strong><span>Held</span></div>
      <div><strong id="bookedCount">0</strong><span>Booked</span></div>
      <div><strong id="selectedCount">0</strong><span>Selected</span></div>
    </section>

    <section class="panel controls">
      <button id="holdBtn">Hold selected seats</button>
      <button id="confirmBtn" disabled>Confirm current hold</button>
      <button id="releaseBtn" disabled>Release hold</button>
      <button id="refreshBtn" class="secondary">Refresh</button>
      <span id="holdInfo" class="hold-info">No active hold</span>
    </section>

    <section class="screen">SCREEN</section>
    <section id="seatGrid" class="seat-grid" aria-live="polite"></section>

    <section class="panel log-panel">
      <h2>Activity</h2>
      <ul id="messages"></ul>
    </section>
  </main>
`;

const grid = document.querySelector('#seatGrid');
const holdBtn = document.querySelector('#holdBtn');
const confirmBtn = document.querySelector('#confirmBtn');
const releaseBtn = document.querySelector('#releaseBtn');
const refreshBtn = document.querySelector('#refreshBtn');
const holdInfo = document.querySelector('#holdInfo');
const messages = document.querySelector('#messages');

holdBtn.addEventListener('click', createHold);
confirmBtn.addEventListener('click', confirmHold);
releaseBtn.addEventListener('click', releaseHold);
refreshBtn.addEventListener('click', loadSeats);

loadSeats();
connectStream();

function getSessionId() {
  const key = 'seat-booking-session-id';
  let value = localStorage.getItem(key);
  if (!value) {
    value = crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`;
    localStorage.setItem(key, value);
  }
  return value;
}

async function api(path, options = {}) {
  const response = await fetch(`${API_BASE}${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options,
  });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) {
    const error = new Error(body.error || `HTTP ${response.status}`);
    error.status = response.status;
    error.body = body;
    throw error;
  }
  return body;
}

async function loadSeats() {
  try {
    const data = await api('/api/seats');
    seats = data.seats;
    selected = new Set([...selected].filter((id) => seatById(id)?.status === 'available'));
    render();
    log('Seat map refreshed.');
  } catch (err) {
    log(`Failed to load seats: ${err.message}`, true);
  }
}

function connectStream() {
  const source = new EventSource(`${API_BASE}/api/stream`);
  source.addEventListener('connected', () => log('Connected to live updates.'));
  source.addEventListener('seats', (event) => {
    const data = JSON.parse(event.data);
    mergeSeats(data.seats || []);
    log(`Live update: ${data.reason || 'status change'} (${(data.seatIds || []).join(', ')}).`);
  });
  source.onerror = () => log('Live update connection interrupted; browser will retry.', true);
}

function mergeSeats(changedSeats) {
  const byId = new Map(seats.map((seat) => [seat.id, seat]));
  for (const seat of changedSeats) {
    byId.set(seat.id, seat);
    if (seat.status !== 'available') selected.delete(seat.id);
    if (currentHold && currentHold.seatIds.includes(seat.id) && seat.status === 'available') {
      // Our hold may have expired or been released by another tab.
      currentHold = null;
      stopCountdown();
    }
  }
  seats = [...byId.values()].sort((a, b) => a.rowLabel.localeCompare(b.rowLabel) || a.seatNumber - b.seatNumber);
  render();
}

function render() {
  renderCounts();
  renderControls();
  renderGrid();
}

function renderCounts() {
  const totals = { available: 0, held: 0, booked: 0 };
  for (const seat of seats) totals[seat.status] += 1;
  document.querySelector('#availableCount').textContent = totals.available;
  document.querySelector('#heldCount').textContent = totals.held;
  document.querySelector('#bookedCount').textContent = totals.booked;
  document.querySelector('#selectedCount').textContent = selected.size;
}

function renderControls() {
  holdBtn.disabled = selected.size === 0 || Boolean(currentHold);
  confirmBtn.disabled = !currentHold;
  releaseBtn.disabled = !currentHold;
  if (!currentHold) holdInfo.textContent = 'No active hold';
}

function renderGrid() {
  const rows = groupBy(seats, (seat) => seat.rowLabel);
  grid.innerHTML = '';
  for (const [rowLabel, rowSeats] of rows) {
    const row = document.createElement('div');
    row.className = 'seat-row';
    const label = document.createElement('div');
    label.className = 'row-label';
    label.textContent = rowLabel;
    row.append(label);

    for (const seat of rowSeats) {
      const button = document.createElement('button');
      const isSelected = selected.has(seat.id);
      const isMine = currentHold?.seatIds.includes(seat.id);
      const isConflict = lastConflictIds.has(seat.id);
      button.className = `seat ${seat.status}${isSelected ? ' selected' : ''}${isMine ? ' mine' : ''}${isConflict ? ' conflict' : ''}`;
      button.type = 'button';
      button.textContent = seat.seatNumber;
      button.title = `${seat.rowLabel}${seat.seatNumber}: ${seat.status}`;
      button.disabled = seat.status !== 'available' && !isSelected;
      button.addEventListener('click', () => toggleSeat(seat));
      row.append(button);
    }
    grid.append(row);
  }
}

function toggleSeat(seat) {
  if (seat.status !== 'available') return;
  lastConflictIds.clear();
  if (selected.has(seat.id)) selected.delete(seat.id);
  else selected.add(seat.id);
  render();
}

async function createHold() {
  const seatIds = [...selected];
  if (!seatIds.length) return;
  try {
    const data = await api('/api/holds', {
      method: 'POST',
      body: JSON.stringify({ seatIds, sessionId }),
    });
    currentHold = data.hold;
    selected.clear();
    lastConflictIds.clear();
    mergeSeats(data.seats);
    startCountdown();
    log(`Hold ${currentHold.id.slice(0, 8)} created for seats ${seatIds.join(', ')}.`);
  } catch (err) {
    if (err.status === 409) {
      lastConflictIds = new Set(err.body.conflictSeatIds || []);
      selected.clear();
      log(`Hold failed; seats already taken: ${[...lastConflictIds].join(', ')}`, true);
      await loadSeats();
      render();
    } else {
      log(`Hold failed: ${err.message}`, true);
    }
  }
}

async function confirmHold() {
  if (!currentHold) return;
  try {
    const data = await api(`/api/holds/${currentHold.id}/confirm`, {
      method: 'POST',
      body: JSON.stringify({ sessionId }),
    });
    mergeSeats(data.seats);
    log(`${data.idempotent ? 'Repeated confirm returned existing' : 'Confirmed'} booking ${data.booking.id.slice(0, 8)}.`);
    currentHold = null;
    stopCountdown();
    render();
  } catch (err) {
    log(`Confirm failed: ${err.message}`, true);
    currentHold = null;
    stopCountdown();
    await loadSeats();
  }
}

async function releaseHold() {
  if (!currentHold) return;
  const holdId = currentHold.id;
  try {
    const data = await api(`/api/holds/${holdId}`, {
      method: 'DELETE',
      body: JSON.stringify({ sessionId }),
    });
    mergeSeats(data.released || []);
    currentHold = null;
    stopCountdown();
    log(`Released hold ${holdId.slice(0, 8)}.`);
    render();
  } catch (err) {
    log(`Release failed: ${err.message}`, true);
  }
}

function startCountdown() {
  stopCountdown();
  updateCountdown();
  countdownTimer = setInterval(updateCountdown, 250);
}

function stopCountdown() {
  if (countdownTimer) clearInterval(countdownTimer);
  countdownTimer = null;
  holdInfo.textContent = 'No active hold';
}

function updateCountdown() {
  if (!currentHold) return stopCountdown();
  const remainingMs = new Date(currentHold.expiresAt).getTime() - Date.now();
  if (remainingMs <= 0) {
    holdInfo.textContent = 'Hold expired; refreshing…';
    currentHold = null;
    stopCountdown();
    loadSeats();
    return;
  }
  holdInfo.textContent = `Hold expires in ${(remainingMs / 1000).toFixed(0)}s`;
}

function groupBy(items, fn) {
  const map = new Map();
  for (const item of items) {
    const key = fn(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  }
  return map;
}

function seatById(id) {
  return seats.find((seat) => seat.id === id);
}

function log(message, isError = false) {
  const item = document.createElement('li');
  item.className = isError ? 'error' : '';
  item.textContent = `${new Date().toLocaleTimeString()} · ${message}`;
  messages.prepend(item);
  while (messages.children.length > 8) messages.lastElementChild.remove();
}
"}

{"path": "src/styles.css", "content": ":root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #172033;
  background: #eef2f7;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
}

* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; }
button { font: inherit; }

.shell {
  width: min(1100px, calc(100% - 32px));
  margin: 0 auto;
  padding: 32px 0;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 24px;
  align-items: center;
  margin-bottom: 20px;
}

.eyebrow {
  text-transform: uppercase;
  letter-spacing: .14em;
  color: #3662ff;
  font-size: 12px;
  font-weight: 800;
  margin: 0 0 6px;
}

h1 { margin: 0; font-size: clamp(32px, 5vw, 56px); line-height: .95; }
h2 { margin: 0 0 12px; font-size: 18px; }
.subtle { margin: 10px 0 0; color: #61708a; }
.session { background: #fff; padding: 12px 16px; border-radius: 999px; box-shadow: 0 10px 30px rgba(26, 38, 67, .08); white-space: nowrap; }

.status-bar {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 16px;
}
.status-bar > div, .panel {
  background: rgba(255,255,255,.9);
  border: 1px solid rgba(117, 132, 164, .18);
  border-radius: 18px;
  box-shadow: 0 16px 40px rgba(35, 53, 84, .08);
}
.status-bar > div { padding: 18px; }
.status-bar strong { display: block; font-size: 32px; }
.status-bar span { color: #66758e; }

.controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 10px;
  padding: 16px;
}

button {
  border: 0;
  border-radius: 12px;
  padding: 10px 14px;
  background: #315cff;
  color: #fff;
  cursor: pointer;
  font-weight: 700;
  box-shadow: 0 10px 24px rgba(49, 92, 255, .22);
}
button:hover:not(:disabled) { transform: translateY(-1px); }
button:disabled { cursor: not-allowed; opacity: .45; box-shadow: none; }
button.secondary { background: #e5eaf4; color: #27344b; box-shadow: none; }
.hold-info { margin-left: auto; color: #44536c; font-weight: 700; }

.screen {
  margin: 28px auto 24px;
  width: min(720px, 85%);
  text-align: center;
  letter-spacing: .35em;
  font-size: 12px;
  font-weight: 800;
  color: #6f7c92;
  background: linear-gradient(180deg, #c9d5e8, #f8fafc);
  border-radius: 10px 10px 60px 60px;
  padding: 12px;
  box-shadow: inset 0 -10px 20px rgba(0,0,0,.04);
}

.seat-grid {
  display: grid;
  gap: 10px;
  overflow-x: auto;
  padding: 8px 0 20px;
}
.seat-row { display: grid; grid-template-columns: 34px repeat(10, 1fr); gap: 8px; min-width: 650px; align-items: center; }
.row-label { font-weight: 900; color: #536178; text-align: center; }
.seat {
  aspect-ratio: 1.25;
  min-height: 46px;
  padding: 0;
  border-radius: 12px 12px 18px 18px;
  color: #162033;
  background: #fff;
  border: 2px solid transparent;
  box-shadow: 0 8px 18px rgba(33, 49, 82, .08);
}
.seat.available { background: #e9fff2; border-color: #57d687; }
.seat.held { background: #fff4d7; border-color: #f0ba38; }
.seat.booked { background: #f0f2f6; color: #8792a3; border-color: #c4ccda; }
.seat.selected { outline: 3px solid #315cff; background: #dbe5ff; }
.seat.mine { box-shadow: 0 0 0 3px rgba(49, 92, 255, .24), 0 8px 18px rgba(33, 49, 82, .08); }
.seat.conflict { animation: pulse .8s ease-in-out 3; border-color: #ed4956; }
@keyframes pulse { 50% { transform: scale(1.07); } }

.log-panel { margin-top: 18px; padding: 18px; }
ul { margin: 0; padding-left: 20px; color: #4e5e77; }
li.error { color: #b4232f; font-weight: 700; }

@media (max-width: 720px) {
  .hero { align-items: flex-start; flex-direction: column; }
  .status-bar { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .hold-info { width: 100%; margin-left: 0; }
}
"}

